"""One shared Step 2 modifier: Blosm input carrier -> GN preparation -> surface."""
from .backend_runtime import Graph, V, choose, rm
from . import prepare
from . import backend
from . import geometry_guard
from . import inputs as contract

NAME = 'Street intersection / Blosm Section solver v1'


def build():
    prep=prepare.build(); surface=backend.build()
    g=Graph(NAME);g.g.is_modifier=True
    g.socket('Geometry','NodeSocketGeometry');g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    g.socket('Valid','NodeSocketBool','OUTPUT');g.socket('Diagnostic Code','NodeSocketInt','OUTPUT')
    s=g.socket('Mesh Resolution','NodeSocketInt',default=1);s.min_value=1;s.max_value=4
    s=g.socket('Height Exaggeration','NodeSocketFloat',default=10.);s.min_value=1.;s.max_value=10.
    g.socket('Grass','NodeSocketBool',default=False);g.socket('Material','NodeSocketMaterial')
    inp=g.node('NodeGroupInput')
    g.section('Interpret Section centerlines and explicit Blosm connectors')
    p=g.node('GeometryNodeGroup','GN preparation from Sections');p.node_tree=prep
    g.bind(inp.outputs['Geometry'],p.inputs['Geometry'])
    header=prepare.view(g,inp.outputs['Geometry'],contract.HEADER)
    datum=rm.read(g,header,'s2_datum',0)
    g.section('Shared direct-quad surface construction')
    n=g.node('GeometryNodeGroup','Shared surface backend');n.node_tree=surface
    g.bind(p.outputs['Geometry'],n.inputs['Geometry'])
    for key in ('Mesh Resolution','Height Exaggeration','Grass','Material'):g.bind(inp.outputs[key],n.inputs[key])
    g.bind(datum,n.inputs['Reference Elevation'])
    good_mesh,minimum_cross,_=geometry_guard.check(g,n.outputs['Geometry'])
    # Requesting grass on an undivided junction legitimately returns no faces.
    profiles=prepare.view(g,inp.outputs['Geometry'],contract.PROFILE)
    has_grass=prepare.stat(g,profiles,rm.named(g,'s2_separator','BOOLEAN'))
    empty_grass=V(g,inp.outputs['Grass'])*(1.-has_grass)
    good_mesh=choose(g,empty_grass,True,good_mesh,'BOOLEAN')
    valid=V(g,p.outputs['Valid'])*good_mesh
    code=choose(g,p.outputs['Valid'],choose(g,good_mesh,0,4,'INT'),p.outputs['Diagnostic Code'],'INT')
    x,y,z=g.separate(g.position())
    ox,oy,_=g.separate(rm.read(g,header,'s2_junction_position',0,'FLOAT_VECTOR'))
    positioned=g.setpos(n.outputs['Geometry'],g.xyz(x+ox,y+oy,z))
    gate=g.node('GeometryNodeSwitch','Reject invalid geometry');gate.input_type='GEOMETRY'
    g.bind(valid,gate.inputs['Switch']);g.bind(positioned,gate.inputs['True'])
    out=g.node('NodeGroupOutput');g.bind(gate.outputs['Output'],out.inputs['Geometry'])
    g.bind(valid,out.inputs['Valid']);g.bind(code,out.inputs['Diagnostic Code'])
    g.g['construction']='Section centerlines and attributes -> native GN mouths/fillets/patches -> direct quad surface'
    g.g['scope']='Initial Step 2: one planar junction, straight local Sections; explicit shared smooth crown for symmetric divided members.'
    g.g['input_schema_version']=contract.SCHEMA_VERSION
