def set_input(obj,name,value):
    """Use Blender 5.2's input-property API, retaining older API fallback."""
    mod=next(m for m in obj.modifiers if m.type=='NODES')
    socket=next(s for s in mod.node_group.interface.items_tree if s.item_type=='SOCKET' and s.in_out=='INPUT' and s.name==name)
    if hasattr(mod,'properties'):
        prop=getattr(mod.properties.inputs,socket.identifier);prop.type='VALUE';prop.value=value
    else:
        mod[socket.identifier]=value
    obj.update_tag()
